#include "normalize.h"

#include <algorithm>
#include <cstring>

#include "unicode_tables.inc"  // generated by tools/gen_unicode_tables.py (defines apg::tables)
#include "utf8.h"

namespace apg {

const char* view_name(ViewKind k) {
    switch (k) {
        case ViewKind::Raw: return "raw";
        case ViewKind::FoldV1: return "fold_v1";
        case ViewKind::TransV1: return "trans_v1";
    }
    return "raw";
}

bool view_from_name(const std::string& name, ViewKind* out) {
    if (name == "raw") { *out = ViewKind::Raw; return true; }
    if (name == "fold_v1") { *out = ViewKind::FoldV1; return true; }
    if (name == "trans_v1") { *out = ViewKind::TransV1; return true; }
    return false;
}

namespace {

// ---- table lookups -------------------------------------------------------------------------------------
bool in_ranges(const tables::Range* r, uint32_t count, uint32_t cp) {
    for (uint32_t i = 0; i < count; ++i) {
        if (cp < r[i].lo) return false;  // ranges are sorted ascending
        if (cp <= r[i].hi) return true;
    }
    return false;
}

inline bool is_ignorable(uint32_t cp) {
    if (cp < 0x80u) return (cp < 0x20u && cp != 0x09u && cp != 0x0Au && cp != 0x0Du) || cp == 0x7Fu;
    return in_ranges(tables::kIgnorable, tables::kIgnorableCount, cp);
}

const tables::CompatEntry* find_compat(uint32_t cp) {
    const tables::CompatEntry* begin = tables::kCompat;
    const tables::CompatEntry* end = tables::kCompat + tables::kCompatCount;
    const tables::CompatEntry* it = std::lower_bound(
        begin, end, cp, [](const tables::CompatEntry& e, uint32_t v) { return e.cp < v; });
    if (it != end && it->cp == cp) return it;
    return nullptr;
}

bool lookup_pair(const tables::Pair* table, uint32_t count, uint32_t cp, uint32_t* to) {
    const tables::Pair* end = table + count;
    const tables::Pair* it = std::lower_bound(
        table, end, cp, [](const tables::Pair& p, uint32_t v) { return p.from < v; });
    if (it != end && it->from == cp) {
        *to = it->to;
        return true;
    }
    return false;
}

bool in_sorted_list(const uint32_t* list, uint32_t count, uint32_t cp) {
    return std::binary_search(list, list + count, cp);
}

inline bool is_py_space(uint32_t cp) { return in_ranges(tables::kPySpace, tables::kPySpaceCount, cp); }

// ---- output builder with optional offsets ---------------------------------------------------------------
class Sink {
public:
    Sink(Normalized& out, bool want_offsets) : out_(out), want_(want_offsets) {}
    void put(uint32_t cp, uint32_t src_off) {
        const size_t before = out_.text.size();
        utf8_append(out_.text, cp);
        if (want_) {
            const size_t added = out_.text.size() - before;
            for (size_t i = 0; i < added; ++i) out_.offsets.push_back(src_off);
        }
    }
    void finish(size_t original_len) {
        if (want_) out_.offsets.push_back(static_cast<uint32_t>(original_len));
    }

private:
    Normalized& out_;
    bool want_;
};

// ---- fold_v1 ---------------------------------------------------------------------------------------------
bool fold_v1(const uint8_t* in, size_t n, bool want_offsets, Normalized& out) {
    bool clean = true;
    for (size_t i = 0; i < n; ++i) {
        const uint8_t c = in[i];
        if (c >= 0x80 || (c < 0x20 && c != 0x09 && c != 0x0A && c != 0x0D) || c == 0x7F) {
            clean = false;
            break;
        }
    }
    if (clean) return false;  // printable ASCII (+ TAB/LF/CR): folding is the identity

    out.text.clear();
    out.offsets.clear();
    out.text.reserve(n);
    if (want_offsets) out.offsets.reserve(n + 1);
    Sink sink(out, want_offsets);
    size_t i = 0;
    while (i < n) {
        uint32_t cp = 0;
        const size_t len = utf8_decode(in + i, n - i, &cp);
        if (!is_ignorable(cp)) {
            const tables::CompatEntry* e = (cp < 0x80u) ? nullptr : find_compat(cp);
            if (e == nullptr) {
                uint32_t to = 0;
                if (cp >= 0x80u && lookup_pair(tables::kAtrConfusables, tables::kAtrConfusableCount, cp, &to)) cp = to;
                sink.put(cp, static_cast<uint32_t>(i));
            } else {
                for (uint32_t k = 0; k < e->len; ++k) {
                    uint32_t c2 = tables::kCompatPool[e->off + k];
                    if (is_ignorable(c2)) continue;
                    uint32_t to = 0;
                    if (c2 >= 0x80u && lookup_pair(tables::kAtrConfusables, tables::kAtrConfusableCount, c2, &to)) c2 = to;
                    sink.put(c2, static_cast<uint32_t>(i));
                }
            }
        }
        i += len;
    }
    sink.finish(n);
    return out.text.size() != n || std::memcmp(out.text.data(), in, n) != 0;
}

// ---- trans_v1 --------------------------------------------------------------------------------------------
struct Ch {
    uint32_t cp;
    uint32_t off;
};

bool trans_v1(const uint8_t* in, size_t n, bool want_offsets, Normalized& out) {
    std::vector<Ch> v;
    v.reserve(n);
    size_t i = 0;
    while (i < n) {
        uint32_t cp = 0;
        const size_t len = utf8_decode(in + i, n - i, &cp);
        v.push_back(Ch{cp, static_cast<uint32_t>(i)});
        i += len;
    }
    // 1. strip (Python str.strip(): Unicode White_Space + \x1c-\x1f)
    size_t lo = 0, hi = v.size();
    while (lo < hi && is_py_space(v[lo].cp)) ++lo;
    while (hi > lo && is_py_space(v[hi - 1].cp)) --hi;
    std::vector<Ch> w;
    w.reserve(hi - lo);
    // 2. zero-width removal  3. homoglyph map  4. \n \t \r -> space
    for (size_t k = lo; k < hi; ++k) {
        uint32_t cp = v[k].cp;
        if (in_sorted_list(tables::kTransZeroWidth, tables::kTransZeroWidthCount, cp)) continue;
        uint32_t to = 0;
        if (lookup_pair(tables::kTransHomoglyphs, tables::kTransHomoglyphCount, cp, &to)) cp = to;
        if (cp == 0x0Au || cp == 0x09u || cp == 0x0Du) cp = 0x20u;
        w.push_back(Ch{cp, v[k].off});
    }
    // 5. collapse runs of ASCII spaces  6. drop characters below 0x20  7. CJK punctuation -> ASCII
    std::vector<Ch> x;
    x.reserve(w.size());
    for (size_t k = 0; k < w.size(); ++k) {
        if (w[k].cp == 0x20u && !x.empty() && x.back().cp == 0x20u) continue;
        x.push_back(w[k]);
    }
    std::vector<Ch> y;
    y.reserve(x.size());
    for (size_t k = 0; k < x.size(); ++k) {
        uint32_t cp = x[k].cp;
        if (cp < 0x20u) continue;
        uint32_t to = 0;
        if (lookup_pair(tables::kTransPunct, tables::kTransPunctCount, cp, &to)) cp = to;
        y.push_back(Ch{cp, x[k].off});
    }
    // 8. final strip
    size_t lo2 = 0, hi2 = y.size();
    while (lo2 < hi2 && is_py_space(y[lo2].cp)) ++lo2;
    while (hi2 > lo2 && is_py_space(y[hi2 - 1].cp)) --hi2;

    out.text.clear();
    out.offsets.clear();
    out.text.reserve(n);
    if (want_offsets) out.offsets.reserve(n + 1);
    Sink sink(out, want_offsets);
    for (size_t k = lo2; k < hi2; ++k) sink.put(y[k].cp, y[k].off);
    sink.finish(n);
    return out.text.size() != n || std::memcmp(out.text.data(), in, n) != 0;
}

}  // namespace

bool normalize(ViewKind kind, const uint8_t* input, size_t n, bool want_offsets, Normalized& out) {
    out.text.clear();
    out.offsets.clear();
    switch (kind) {
        case ViewKind::Raw:
            return false;
        case ViewKind::FoldV1: {
            const bool changed = fold_v1(input, n, want_offsets, out);
            if (!changed) {
                out.text.clear();
                out.offsets.clear();
            }
            return changed;
        }
        case ViewKind::TransV1: {
            const bool changed = trans_v1(input, n, want_offsets, out);
            if (!changed) {
                out.text.clear();
                out.offsets.clear();
            }
            return changed;
        }
    }
    return false;
}

}  // namespace apg
